uniform vec2 u_resolution;
uniform float iTime;

// A simple SDF representing a micro-carved profile slice
float de_prayer_nut_relief(vec2 p) {
    // Tiling space into periodic grid cells within the log-polar domain
    vec2 cell = fraction(p * 4.0 - 0.5) - 0.5;
    // An intricate layered relief motif
    return length(cell) - 0.35 + 0.05 * sin(cell.x * 20.0 + iTime);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 1. Normalize and center coordinates
    vec2 uv = (fragCoord - u_resolution.xy * 0.5) / u_resolution.y; //

    // 2. Capture the radius before the warp
    float r = length(uv); //

    // 3. Apply Log-Polar mapping (The LUT Domain Warp)
    vec2 st = vec2(log(r) - iTime * 0.5, atan(uv.y, uv.x)); //

    // 4. Evaluate the SDF in warped space
    float distance_in_warped_space = de_prayer_nut_relief(st);

    // 5. THE FIX: Multiply by 'r' to restore valid metric distance
    float true_sdf = distance_in_warped_space * r; //

    // 6. Camera Obscura Shutter Emulation (Simulating deep exposure blur)
    float mask = smoothstep(0.0, 0.02 / r, abs(true_sdf));
    vec3 color = mix(vec3(0.24, 0.15, 0.08), vec3(0.02), mask); // Rich boxwood tones

    // Vignette mimicking a real pinhole projection falloff
    color *= smoothstep(0.8, 0.2, r); 

    fragColor = vec4(color, 1.0);
}

